import unicodedata


def slugify(s):
    s = s.lower()
    out = []
    for ch in s:
        if ch.isalnum():
            # Fold accented/unicode characters to their ASCII base (e.g. õ -> o)
            for c in unicodedata.normalize('NFKD', ch):
                if c.isascii() and c.isalnum():
                    out.append(c)
        else:
            out.append('-')
    slug = ''.join(out)
    # Collapse multiple separators and strip leading/trailing ones
    while '--' in slug:
        slug = slug.replace('--', '-')
    return slug.strip('-')

